-- V23.10 provider/fund glossary expansion
-- Safe to run repeatedly. This increases selectable pension/investment fund coverage without overwriting user-owned funds.
-- Values with null fee/unit price are search candidates and should be refreshed from provider docs before acceptance.

create table if not exists investment_provider_glossary (
  id text primary key,
  provider_name text not null,
  category text not null check (category in ('pension','investment','both')),
  offerings jsonb not null default '[]'::jsonb,
  default_annual_platform_fee_percent numeric(8,4),
  default_fixed_monthly_fee numeric(12,2),
  default_fx_fee_percent numeric(8,4),
  supports_pies boolean not null default false,
  supports_fractional_shares boolean not null default false,
  supports_fund_search boolean not null default false,
  docs jsonb not null default '[]'::jsonb,
  notes text,
  last_reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists investment_provider_fund_glossary (
  id text primary key,
  provider_id text references investment_provider_glossary(id) on delete cascade,
  fund_name text not null,
  fund_code text,
  group_label text,
  annual_fund_fee_percent numeric(10,6),
  unit_price numeric(18,8),
  unit_price_quote_unit text default 'gbp',
  source_url text,
  confidence integer not null default 50,
  notes text,
  last_reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table investment_provider_glossary enable row level security;
alter table investment_provider_fund_glossary enable row level security;

drop policy if exists "Authenticated users can read provider glossary" on investment_provider_glossary;
create policy "Authenticated users can read provider glossary" on investment_provider_glossary for select to authenticated using (true);
drop policy if exists "Authenticated users can read provider fund glossary" on investment_provider_fund_glossary;
create policy "Authenticated users can read provider fund glossary" on investment_provider_fund_glossary for select to authenticated using (true);

