on conflict (id) do update set
  provider_id=excluded.provider_id,
  fund_name=excluded.fund_name,
  fund_code=excluded.fund_code,
  group_label=excluded.group_label,
  annual_fund_fee_percent=coalesce(excluded.annual_fund_fee_percent, investment_provider_fund_glossary.annual_fund_fee_percent),
  unit_price=coalesce(excluded.unit_price, investment_provider_fund_glossary.unit_price),
  unit_price_quote_unit=excluded.unit_price_quote_unit,
  source_url=coalesce(excluded.source_url, investment_provider_fund_glossary.source_url),
  confidence=greatest(investment_provider_fund_glossary.confidence, excluded.confidence),
  notes=excluded.notes,
  last_reviewed_at=excluded.last_reviewed_at,
  updated_at=now();


create index if not exists idx_investment_provider_fund_glossary_search on investment_provider_fund_glossary using gin (to_tsvector('english', fund_name || ' ' || coalesce(fund_code,'') || ' ' || coalesce(group_label,'')));
notify pgrst, 'reload schema';
